<?php
$labels=['draft'=>'Rascunho','sent'=>'Liberado','viewed'=>'Visualizado','signed'=>'Assinado','cancelled'=>'Cancelado'];
$rules=['percentage_commission'=>'Comissão percentual','fixed_monthly'=>'Mensalidade fixa','hybrid'=>'Mensalidade + comissão','per_enrollment'=>'Valor por matrícula'];
$processingLabels=['central_monthly_settlement'=>'Conta central · repasse mensal','central_automatic_split'=>'Conta central · split automático','franchise_asaas'=>'Asaas exclusivo da franquia'];
$commercialRule=trim((string)($contract['commercial_rule']??''));
if($commercialRule==='')$commercialRule=($contract['commercial_model']??'')==='fixed_plus_percentage'?((float)($contract['sales_fee_percentage']??0)>0?'hybrid':'fixed_monthly'):'percentage_commission';
$financialProcessing=trim((string)($contract['financial_processing']??''));
if($financialProcessing==='')$financialProcessing=(float)($contract['sales_fee_percentage']??0)>0?'central_automatic_split':'central_monthly_settlement';
$flowActive=($contract['commercial_flow_status']??'pending')==='active';
$splitRequired=$financialProcessing==='central_automatic_split';
$exclusiveRequired=$financialProcessing==='franchise_asaas';
$walletReady=!empty($contract['asaas_wallet_id'])&&($contract['asaas_wallet_status']??'')==='validated'&&(int)($contract['split_enabled']??0)===1;
$exclusiveReady=($contract['finance_account_mode']??'')==='exclusive'&&(int)($contract['finance_integration_active']??0)===1&&($contract['finance_integration_test_status']??'')==='success';
$processingReady=(!$splitRequired||$walletReady)&&(!$exclusiveRequired||$exclusiveReady);
$organizationId=(int)($contract['organization_id']??0);
$cancelled=$contract['status']==='cancelled';
$signed=!empty($contract['signed_at'])||$contract['status']==='signed';
$monthly=(float)($contract['monthly_fixed_amount']??0);
$centralPercentage=(float)($contract['sales_fee_percentage']??0);
$franchisePercentage=(float)($contract['franchise_fee_percentage']??0);
if($centralPercentage>0&&$franchisePercentage<=0)$franchisePercentage=100-$centralPercentage;
$perEnrollment=(float)($contract['fixed_fee_per_enrollment']??0);
$commercialReady=!$cancelled&&$signed&&$processingReady;
$signatureSteps=[
 ['label'=>'Gerado','date'=>$contract['created_at']??null],
 ['label'=>'Liberado','date'=>$contract['sent_at']??null],
 ['label'=>'Visualizado','date'=>$contract['viewed_at']??null],
 ['label'=>'Assinado','date'=>$contract['signed_at']??null],
];
$processingTitle=$splitRequired?'Wallet e split':($exclusiveRequired?'Asaas exclusivo':'Fechamento mensal');
$processingDetail=$splitRequired?($walletReady?'Wallet validada e split habilitado.':'Wallet ou split pendente.'):($exclusiveRequired?($exclusiveReady?'Integração exclusiva testada e ativa.':'Integração exclusiva pendente.'):'Fechamento no dia '.(int)($contract['closing_day']??30).' e repasse no dia '.(int)($contract['settlement_day']??10).'.');
?>
