<?php if($cancelled):?><section class="alert alert-danger mb-4" id="cancelamento"><strong><i class="fa-solid fa-circle-xmark"></i> Contrato cancelado</strong><p class="mb-1"><?= $escape((string)($contract['cancelled_reason']??'Motivo não informado.')) ?></p><small>Cancelado em <?= !empty($contract['cancelled_at'])?$escape(date('d/m/Y H:i',strtotime((string)$contract['cancelled_at']))):'data não registrada' ?> por <?= $escape((string)($contract['cancelled_by_name']?:'Sistema')) ?>. O histórico foi preservado.</small></section><?php endif;?>

<section class="card p-4 mb-4"><div class="contract-summary-grid">
 <div><small>Regra comercial</small><strong><?= $escape($rules[$commercialRule]??'Legado') ?></strong></div>
 <div><small>Processamento financeiro</small><strong><?= $escape($processingLabels[$financialProcessing]??'Não definido') ?></strong></div>
 <div><small>Vigência</small><strong><?= $contract['valid_from']?$escape(date('d/m/Y',strtotime((string)$contract['valid_from']))):'—' ?> a <?= $contract['valid_until']?$escape(date('d/m/Y',strtotime((string)$contract['valid_until']))):'indeterminada' ?></strong></div>
 <div><small>Mensalidade</small><strong><?= $monthly>0?'R$ '.number_format($monthly,2,',','.'):'Sem mensalidade fixa' ?></strong></div>
 <div><small>Divisão por venda</small><strong><?= $centralPercentage>0?'Mundo Inter '.number_format($centralPercentage,2,',','.').'% · Franquia '.number_format($franchisePercentage,2,',','.').'%':'Não se aplica' ?></strong></div>
 <div><small>Valor por matrícula</small><strong><?= $perEnrollment>0?'R$ '.number_format($perEnrollment,2,',','.'):'Não se aplica' ?></strong></div>
</div></section>

<section class="card mb-4"><div class="card-header"><div><p class="eyebrow">Operação comercial</p><h2><?= $cancelled?'Regra bloqueada':($flowActive?'Regra ativa':'Aguardando ativação') ?></h2><p class="meta"><?= $cancelled?'O cancelamento interrompeu o uso desta regra em novas vendas.':($flowActive?'As novas vendas já utilizam as condições deste contrato.':($commercialReady?'Todos os requisitos estão prontos para ativação.':'Ainda existem requisitos pendentes.')) ?></p></div><div class="page-actions">
 <?php if($cancelled):?><span class="badge badge-danger"><i class="fa-solid fa-ban"></i> Bloqueada</span>
