 <?php elseif($splitRequired&&!$walletReady&&$organizationId>0):?><a class="button button-primary" href="<?= $escape($basePath) ?>/admin/organizations/<?= $organizationId ?>#operacao-comercial"><i class="fa-solid fa-wallet"></i> Configurar Wallet</a>
 <?php elseif($exclusiveRequired&&!$exclusiveReady&&$organizationId>0):?><a class="button button-primary" href="<?= $escape($basePath) ?>/admin/organizations/<?= $organizationId ?>/edit#integracoes"><i class="fa-solid fa-plug"></i> Configurar Asaas exclusivo</a>
 <?php else:?><form method="post" action="<?= $escape($basePath) ?>/admin/franchise-contracts/<?= (int)$contract['id'] ?>/activate-commercial-flow"><?= $csrfField ?><button class="button button-primary" type="submit" data-confirm-submit="Ativar esta regra para as novas vendas da franquia?"><i class="fa-solid fa-circle-play"></i> Ativar regra comercial</button></form><?php endif;?>
</div></div><div class="p-4 pt-0"><div class="contract-operation-grid"><div><i class="fa-solid <?= $signed?'fa-circle-check text-success':'fa-clock text-warning' ?>"></i><strong class="d-block mt-2">Contrato assinado</strong><small class="meta"><?= $signed?'Concluído':'Pendente' ?></small></div><div><i class="fa-solid <?= $processingReady?'fa-circle-check text-success':'fa-clock text-warning' ?>"></i><strong class="d-block mt-2"><?= $escape($processingTitle) ?></strong><small class="meta"><?= $escape($processingDetail) ?></small></div><div><i class="fa-solid <?= $flowActive?'fa-circle-check text-success':'fa-clock text-warning' ?>"></i><strong class="d-block mt-2">Novas vendas</strong><small class="meta"><?= $flowActive?'Regra aplicada':'Aguardando ativação' ?></small></div></div>
<?php if($splitRequired&&!$walletReady):?><div class="alert alert-warning mt-3 mb-0"><strong>Ativação pendente.</strong> Valide a Wallet da franquia e habilite o split automático.</div><?php endif;?>
<?php if($exclusiveRequired&&!$exclusiveReady):?><div class="alert alert-warning mt-3 mb-0"><strong>Ativação pendente.</strong> A conta Asaas exclusiva da franquia precisa estar salva, testada e ativa.</div><?php endif;?></div></section>

<section class="card mb-4" id="assinatura"><div class="card-header"><div><h2>Assinatura e evidências</h2><p class="meta">Acompanhe o processo e envie o link manualmente ao responsável.</p></div><?php if($contract['status']==='draft'):?><form method="post" action="<?= $escape($basePath) ?>/admin/franchise-contracts/<?= (int)$contract['id'] ?>/send"><?= $csrfField ?><button class="button button-primary" type="submit" data-confirm-submit="Liberar este contrato para assinatura?"><i class="fa-solid fa-paper-plane"></i> Liberar assinatura</button></form><?php endif;?></div><div class="p-4"><div class="contract-timeline mb-4"><?php foreach($signatureSteps as$step):?><div><i class="fa-solid <?= $step['date']?'fa-circle-check text-success':'fa-clock text-warning' ?>"></i><small class="mt-2"><?= $escape($step['label']) ?></small><strong><?= $step['date']?$escape(date('d/m/Y H:i',strtotime((string)$step['date']))):'Pendente' ?></strong></div><?php endforeach;?></div>
<?php if(!$cancelled&&in_array($contract['status'],['sent','viewed','signed'],true)):?><div class="row g-3"><div class="col-lg-7"><label>Link público de assinatura<div class="input-copy-row"><input id="contract-public-url" readonly value="<?= $escape($publicUrl) ?>"><button class="button button-secondary button-icon" type="button" data-copy-target="contract-public-url" title="Copiar link"><i class="fa-solid fa-copy"></i></button></div></label><small>O envio à franquia permanece manual.</small></div><?php if($signed):?><div class="col-lg-5"><strong><?= $escape((string)$contract['signer_name']) ?></strong><p class="meta mb-1"><?= $escape((string)$contract['signer_email']) ?> · Documento <?= $escape((string)$contract['signer_document']) ?></p><small>IP <?= $escape((string)$contract['signer_ip']) ?></small></div><?php endif;?></div><?php elseif($cancelled&&$signed):?><div class="border rounded-3 p-3"><strong><?= $escape((string)$contract['signer_name']) ?></strong><p class="meta mb-1"><?= $escape((string)$contract['signer_email']) ?> · Documento <?= $escape((string)$contract['signer_document']) ?></p><small>Assinatura histórica preservada · IP <?= $escape((string)$contract['signer_ip']) ?></small></div><?php endif;?>
<?php if($signed):?><details class="mt-3"><summary><strong>Ver integridade da assinatura</strong></summary><div class="mt-2"><label>Hash da evidência<input readonly value="<?= $escape((string)$contract['evidence_hash']) ?>"></label><button class="button button-secondary mt-2" type="button" data-print-page><i class="fa-solid fa-print"></i> Salvar contrato em PDF</button></div></details><?php endif;?></div></section>

