<?php elseif($signed&&!$cancelled):?><p>Gere o link recorrente somente quando desejar enviá-lo à franquia.</p><?php if(!$asaasReady):?><div class="alert alert-warning">A integração Asaas central precisa estar ativa.</div><?php endif;?><form method="post" action="<?= $escape($basePath) ?>/admin/franchise-contracts/<?= (int)$contract['id'] ?>/recurring-link"><?= $csrfField ?><button class="button button-primary" type="submit" <?= !$asaasReady?'disabled':'' ?> data-confirm-submit="Gerar o link mensal real no Asaas?"><i class="fa-solid fa-link"></i> Gerar link mensal</button></form>
<?php else:?><p class="mb-0">Disponível depois da assinatura do contrato.</p><?php endif;?><?php if(!empty($contract['billing_error'])):?><div class="alert alert-danger mt-3 mb-0"><?= $escape((string)$contract['billing_error']) ?></div><?php endif;?></div></section>

